const params = {
  type: "object",
  properties: {
    order_number: {
      type: "string",
      description: "4-6 digit order number as the customer wrote it."
    }
  },
  required: ["order_number"],
  additionalProperties: false
};

const description =
  "Look up one order on the signed-in customer's account. " +
  "It returns status and update time only. It cannot change an order. " +
  "Caller identity comes from authenticated application context, never arguments.";

const openaiTool = {
  type: "function", name: "orders_get_status", description,
  parameters: params, strict: true
};
const claudeTool = {
  name: "orders_get_status", description, input_schema: params, strict: true
};
const geminiTool = {
  type: "function", name: "orders_get_status", description, parameters: params
};

// Runtime correlation:
// OpenAI: function_call.call_id -> function_call_output.call_id
// Claude: tool_use.id -> tool_result.tool_use_id
// Gemini Interactions: function_call.id -> function_result.call_id

// Administrator setup for an application-owned orders table:
//   CREATE ROLE support_tool LOGIN NOSUPERUSER NOBYPASSRLS;
//   GRANT SELECT (order_number, status, updated_at, account_id) ON orders TO support_tool;
//   ALTER ROLE support_tool SET statement_timeout = '2s';
//   ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
//   CREATE POLICY support_orders ON orders FOR SELECT TO support_tool
//     USING (account_id::text = current_setting('app.account_id', true));
// support_tool must not own orders or inherit a bypass role.

interface Connection { query(sql: string, params: unknown[]): Promise<{ rows: Record<string, unknown>[] }>; }
interface Db {
  // BEGIN + callback + COMMIT; ROLLBACK on error, on ONE checked-out connection.
  transaction<T>(work: (tx: Connection) => Promise<T>): Promise<T>;
}
interface Session { accountId: string }

export async function runSqlTool(db: Db, name: string, input: unknown, s: Session) {
  if (name !== "orders_get_status") return { isError: true, text: "Unknown tool. Available: orders_get_status." };
  if (!input || typeof input !== "object" || Array.isArray(input)) return { isError: true, text: "Expected order_number." };
  const a = input as Record<string, unknown>;
  if (Object.keys(a).length !== 1 || typeof a.order_number !== "string" || !/^\d{4,6}$/.test(a.order_number))
    return { isError: true, text: "order_number must be 4-6 digits; no extra fields." };
  if (!s.accountId) return { isError: true, text: "Authenticated account required." };
  try {
    const { rows } = await db.transaction(async (tx) => {
      // Trusted session identity, never a model argument. true = transaction-local.
      await tx.query("SELECT set_config('app.account_id', $1, true)", [s.accountId]);
      return tx.query("SELECT order_number, status, updated_at FROM orders WHERE account_id = $1 AND order_number = $2 LIMIT 1", [s.accountId, a.order_number]);
    });
    return { isError: false, text: rows.length ? JSON.stringify(rows[0]) : "No matching order on this account." };
  } catch {
    return { isError: true, text: "Order lookup unavailable; do not assume the order is absent." };
  }
}

const helpdeskTool = {
  type: "function",
  name: "helpdesk_tickets",
  description:
    "Read or comment on the signed-in user's helpdesk tickets. Use list_open to find tickets, get for one " +
    "ticket's detail, and add_comment to reply on a ticket. It cannot close, reassign, or delete tickets. " +
    "list_open returns at most 20 tickets, newest first; ticket_id and comment are null when not needed.",
  strict: true,
  parameters: {
    type: "object",
    properties: {
      action: { type: "string", enum: ["list_open", "get", "add_comment"] },
      ticket_id: { type: ["string", "null"] },
      comment: { type: ["string", "null"] },
    },
    required: ["action", "ticket_id", "comment"],
    additionalProperties: false,
  },
};

type Args = { action: "list_open" | "get" | "add_comment"; ticket_id: string | null; comment: string | null };

const ROUTES = {
  list_open: (_: Args) => ({ method: "GET", path: "/tickets?status=open&limit=20" }),
  get: (a: Args) => ({ method: "GET", path: `/tickets/${encodeURIComponent(need(a.ticket_id))}` }),
  add_comment: (a: Args) => ({
    method: "POST",
    path: `/tickets/${encodeURIComponent(need(a.ticket_id))}/comments`,
    body: JSON.stringify({ text: need(a.comment) }),
  }),
};

function need(v: string | null): string {
  if (!v) throw new Error("This action needs ticket_id (and comment for add_comment).");
  return v;
}

function parseArgs(input: unknown): Args {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("Invalid arguments.");
  const a = input as Record<string, unknown>;
  if (Object.keys(a).length !== 3 || !Object.hasOwn(ROUTES, String(a.action))) throw new Error("Invalid action or fields.");
  if (a.action === "list_open") {
    if (a.ticket_id !== null || a.comment !== null) throw new Error("list_open requires null ticket_id and comment.");
  } else {
    if (typeof a.ticket_id !== "string" || !/^[a-zA-Z0-9_-]{1,128}$/.test(a.ticket_id)) throw new Error("Invalid ticket_id.");
    if (a.action === "get" ? a.comment !== null : typeof a.comment !== "string" || !a.comment.trim() || a.comment.length > 2000) throw new Error("Invalid comment.");
  }
  return a as Args;
}

export async function runHelpdesk(input: unknown, session: { userToken: string }, baseUrl: string) {
  let args: Args;
  try { args = parseArgs(input); } catch { return { isError: true, text: "Invalid helpdesk arguments; check the allowed action and fields." }; }
  // baseUrl is trusted deployment configuration; the downstream API authorizes the user.
  const r = ROUTES[args.action](args);          // enum-checked; no model-supplied URL
  const res = await fetch(baseUrl + r.path, {
    method: r.method,
    headers: { Authorization: `Bearer ${session.userToken}`, "Content-Type": "application/json" },
    body: "body" in r ? r.body : undefined,
  });
  return { isError: !res.ok, text: res.ok ? await res.text() : `Helpdesk returned ${res.status}.` };
}

